<?php
declare(strict_types=1);require dirname(__DIR__).'/app/bootstrap.php';$user=require_permission('knowledge.manage');\App\Core\Tenant::enforceActive((int)$user['tenant_id']);$t=(int)$user['tenant_id'];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$title=trim($_POST['title']??'');$content=trim($_POST['content']??'');if($title&&$content){$st=db()->prepare("INSERT INTO knowledge_chunks(tenant_id,title,source_url,source_type,content,is_official,active,created_at,updated_at)VALUES(:t,:title,:url,:type,:content,:official,1,NOW(),NOW())");$st->execute(['t'=>$t,'title'=>$title,'url'=>trim($_POST['source_url']??'')?:null,'type'=>trim($_POST['source_type']??'manual')?:'manual','content'=>$content,'official'=>isset($_POST['is_official'])?1:0]);audit('knowledge.create','knowledge_chunk',(int)db()->lastInsertId(),[]);flash('success','Fonte adicionada à base interna.');redirect('knowledge/index.php');}}$st=db()->prepare("SELECT * FROM knowledge_chunks WHERE tenant_id=:t OR tenant_id IS NULL ORDER BY is_official DESC,updated_at DESC LIMIT 100");$st->execute(['t'=>$t]);$rows=$st->fetchAll();layout('Base científica',function()use($rows){?><div class="page-head"><div><span class="eyebrow">RAG</span><h1>Base científica e normativa</h1><p>Inclua apenas materiais cujo uso e armazenamento estejam autorizados. A IA recebe trechos recuperados desta base.</p></div></div><div class="grid-2"><form method="post" class="card form-grid"><?=csrf_field()?><h2>Adicionar fonte</h2><div class="field"><label>Título</label><input name="title" required></div><div class="form-row"><div class="field"><label>Tipo</label><select name="source_type"><option value="manual">Manual / nota</option><option value="cfp">CFP / normativa</option><option value="article">Artigo científico</option></select></div><div class="field"><label>URL da fonte</label><input type="url" name="source_url"></div></div><div class="field"><label>Trecho autorizado</label><textarea name="content" style="min-height:240px" required></textarea></div><label><input type="checkbox" name="is_official"> Marcar como fonte oficial/verificada pelo administrador</label><button class="button">Adicionar à base</button></form><section class="card"><h2>Fontes disponíveis</h2><div class="stack"><?php if(!$rows):?><p class="muted">Base vazia. O modo RAG deve informar que não há fonte suficiente.</p><?php endif?><?php foreach($rows as $r):?><article class="record"><div class="split-actions"><span class="status"><?=e($r['source_type'])?></span><?php if($r['is_official']):?><span class="status approved">verificada</span><?php endif?></div><strong><?=e($r['title'])?></strong><p class="muted"><?=e(mb_substr($r['content'],0,180))?><?=mb_strlen($r['content'])>180?'…':''?></p><?php if($r['source_url']):?><a href="<?=e($r['source_url'])?>" target="_blank" rel="noopener">Abrir origem</a><?php endif?></article><?php endforeach?></div></section></div><?php },['active'=>'knowledge']);
